import{_ as t,o as e,c as r,a0 as i}from"./chunks/framework.CWG7uS0z.js";const u=JSON.parse('{"title":"开发规范与守则 (Engineering Standards)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/standards.md","filePath":"guide/standards.md"}'),o={name:"guide/standards.md"};function n(l,a,s,d,c,g){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="开发规范与守则-engineering-standards" tabindex="-1">开发规范与守则 (Engineering Standards) <a class="header-anchor" href="#开发规范与守则-engineering-standards" aria-label="Permalink to &quot;开发规范与守则 (Engineering Standards)&quot;">​</a></h1><p>本文档确立了 Farmer Platform 的<strong>核心技术原则</strong>与<strong>代码规范</strong>。这是项目保持高内聚、低耦合，以及长期可维护性的基石。在本项目中进行任何修改时，<strong>必须绝对服从</strong>以下约定。</p><hr><h2 id="_1-架构完整性-technical-integrity" tabindex="-1">1. 架构完整性 (Technical Integrity) <a class="header-anchor" href="#_1-架构完整性-technical-integrity" aria-label="Permalink to &quot;1. 架构完整性 (Technical Integrity)&quot;">​</a></h2><h3 id="_1-1-纯数据驱动-strict-data-driven" tabindex="-1">1.1 纯数据驱动 (Strict Data-Driven) <a class="header-anchor" href="#_1-1-纯数据驱动-strict-data-driven" aria-label="Permalink to &quot;1.1 纯数据驱动 (Strict Data-Driven)&quot;">​</a></h3><ul><li><strong>拒绝 Mock 数据</strong>: 所有的前端业务数据必须真实地来源于 Spring Boot 提供的 RESTful 接口。项目中曾存在的静态 Mock 数据必须彻底被淘汰，禁止新功能引入任何形式的硬编码业务数据。</li><li><strong>状态单一真实源 (Single Source of Truth)</strong>: 全局的分类、状态码字典（如订单状态、商品分类）统一存放在 <code>src/utils/constants.js</code> 中，或由后端接口统一维护，禁止在组件中硬编码判断。</li></ul><h3 id="_1-2-外科手术式更新-surgical-updates" tabindex="-1">1.2 外科手术式更新 (Surgical Updates) <a class="header-anchor" href="#_1-2-外科手术式更新-surgical-updates" aria-label="Permalink to &quot;1.2 外科手术式更新 (Surgical Updates)&quot;">​</a></h3><ul><li><strong>最小化变更</strong>: 无论进行修复还是重构，只触及与任务直接相关的代码逻辑。不要因为“顺手”而去修改周边不相关的格式化或逻辑，除非存在明显致命错误。</li><li><strong>清理自己造成的废弃代码 (Orphan Cleanup)</strong>: 如果您的代码变更导致某些 import、变量或函数不再被调用，您有责任将它们清理干净。</li></ul><h3 id="_1-3-服务端核心原则" tabindex="-1">1.3 服务端核心原则 <a class="header-anchor" href="#_1-3-服务端核心原则" aria-label="Permalink to &quot;1.3 服务端核心原则&quot;">​</a></h3><ul><li><strong>分页优先 (Pagination First)</strong>: 任何返回列表的 API（如获取商品列表、文章列表、用户列表等），无论数据量大小，<strong>必须</strong>使用 Spring Data JPA 的 <code>Pageable</code>，并包装在标准化的 <code>PagedResponse&lt;T&gt;</code> 中返回。</li><li><strong>规范化响应包装</strong>: 所有 API 必须返回包裹了状态码、消息和数据的统一数据结构 <code>ApiResponse&lt;T&gt;</code>。</li></ul><hr><h2 id="_2-智能化开发规范-ai-llm-integration" tabindex="-1">2. 智能化开发规范 (AI &amp; LLM Integration) <a class="header-anchor" href="#_2-智能化开发规范-ai-llm-integration" aria-label="Permalink to &quot;2. 智能化开发规范 (AI &amp; LLM Integration)&quot;">​</a></h2><p>基于 DeepSeek 与 LangChain 的 AI Agent 系统需要遵守特定的上下文安全守则。</p><h3 id="_2-1-安全的上下文管理-safe-summary-mode" tabindex="-1">2.1 安全的上下文管理 (Safe Summary Mode) <a class="header-anchor" href="#_2-1-安全的上下文管理-safe-summary-mode" aria-label="Permalink to &quot;2.1 安全的上下文管理 (Safe Summary Mode)&quot;">​</a></h3><p>为了避免大语言模型出现“幻觉”或者输出泄露系统底层 Prompt 的 XML/SML 标签，我们实施了两步安全策略：</p><ul><li><strong>步骤 1</strong>: 识别用户的意图并触发对应的 Tool Call，调用后端接口获取纯净 JSON 格式的业务数据。</li><li><strong>步骤 2</strong>: <strong>丢弃并重置对话历史</strong>。不将带有繁杂 Tool Call 的内部调用记录给到模型生成最终总结，而是发起一次全新的无状态总结请求。</li></ul><h3 id="_2-2-结果导向的简洁输出-concise-output" tabindex="-1">2.2 结果导向的简洁输出 (Concise Output) <a class="header-anchor" href="#_2-2-结果导向的简洁输出-concise-output" aria-label="Permalink to &quot;2.2 结果导向的简洁输出 (Concise Output)&quot;">​</a></h3><p>AI 的分析报告不能长篇大论。</p><ul><li>必须采用要点式（Bullet points）输出，限制在 3-4 个要点。</li><li>限制输出字数（约 200 字），直接给出“业务洞察”与“行动建议”。</li></ul><hr><h2 id="_3-安全性与拦截器逻辑-security" tabindex="-1">3. 安全性与拦截器逻辑 (Security) <a class="header-anchor" href="#_3-安全性与拦截器逻辑-security" aria-label="Permalink to &quot;3. 安全性与拦截器逻辑 (Security)&quot;">​</a></h2><h3 id="_3-1-jwt-无状态认证" tabindex="-1">3.1 JWT 无状态认证 <a class="header-anchor" href="#_3-1-jwt-无状态认证" aria-label="Permalink to &quot;3.1 JWT 无状态认证&quot;">​</a></h3><ul><li><strong>AuthInterceptor 规范</strong>: 所有受保护的接口必须经过 <code>AuthInterceptor</code> 拦截。</li><li><strong>OPTIONS 放行</strong>: <code>AuthInterceptor</code> 必须无条件放行 HTTP 的 <code>OPTIONS</code> 请求（用于 CORS 跨域预检），否则会导致前端跨域报错。</li><li><strong>公共白名单</strong>: <code>/login</code>, <code>/register</code>, 以及公开查询商品的接口应当被显式放行。</li></ul><h3 id="_3-2-敏感信息隔离" tabindex="-1">3.2 敏感信息隔离 <a class="header-anchor" href="#_3-2-敏感信息隔离" aria-label="Permalink to &quot;3.2 敏感信息隔离&quot;">​</a></h3><ul><li>永远不要将生产环境的真实 JWT Secret、数据库密码提交到代码仓库。开发环境的密钥（如 MySQL 密码 <code>z236244462</code>）仅限本地开发测试使用。</li></ul><hr><h2 id="_4-karpathy-指导方针-karpathy-inspired-coding" tabindex="-1">4. Karpathy 指导方针 (Karpathy-Inspired Coding) <a class="header-anchor" href="#_4-karpathy-指导方针-karpathy-inspired-coding" aria-label="Permalink to &quot;4. Karpathy 指导方针 (Karpathy-Inspired Coding)&quot;">​</a></h2><p>本项目严格贯彻以下极简与高效开发哲学：</p><ol><li><strong>想清楚再写代码 (Think Before Coding)</strong>: 遇到模糊的需求，先阐述理解再动手，不要假设用户的意图。如果可以更简单地实现，直接指出。</li><li><strong>简单至上 (Simplicity First)</strong>: 写出能解决问题的最少代码。不编写推测性的、未经要求的功能（如过度的接口抽象、“万一未来用到”的扩展）。如果花了 200 行解决 50 行就能解决的问题，<strong>重写它</strong>。</li><li><strong>目标导向 (Goal-Driven Execution)</strong>: 每一个变更必须有可以被验证的测试目标。无论是 Debug 还是 Feature，执行逻辑应为：<code>重现/明确验证目标 -&gt; 编写代码 -&gt; 验证通过</code> 的独立闭环。</li></ol>',29)])])}const p=t(o,[["render",n]]);export{u as __pageData,p as default};
